(()=>{if(window.__JMW_DASHBOARD_FIX_20260828__)return;window.__JMW_DASHBOARD_FIX_20260828__=true;const $=id=>document.getElementById(id);const run=async()=>{try{const t=localStorage.getItem('jmw_token'),h={Authorization:`Bearer ${t}`},[d,u,r]=await Promise.all([fetch('/api/devices',{cache:'no-store',headers:h}),fetch('/api/users',{cache:'no-store',headers:h}),fetch('/api/repairs',{cache:'no-store',headers:h})]);if(!d.ok||!u.ok||!r.ok)return;const devices=await d.json(),users=await u.json(),repairs=await r.json();const active=Array.isArray(users)?users.filter(x=>x.active!==false):[];const ds=Array.isArray(devices)?devices:[];const assigned=new Set(active.filter(x=>x.device_id).map(x=>Number(x.device_id)));const available=ds.filter(x=>x.status==='available').length;const repair=ds.filter(x=>x.status==='repair').length;const retired=ds.filter(x=>x.status==='retired').length;const assignedCount=ds.filter(x=>assigned.has(Number(x.id))&&x.status!=='repair'&&x.status!=='retired').length;const today=new Date().toISOString().slice(0,10);const overdue=active.filter(x=>{const v=String(x.return_due_date||'').slice(0,10);return v&&v<today}).length;if($('total'))$('total').textContent=ds.length;if($('available'))$('available').textContent=available;if($('assigned'))$('assigned').textContent=assignedCount;if($('repair'))$('repair').textContent=repair;if($('overdue'))$('overdue').textContent=overdue;if($('sumUsers'))$('sumUsers').textContent=active.length;if($('sumRepairs'))$('sumRepairs').textContent=Array.isArray(repairs)?repairs.length:0;if($('sumOpenRepairs'))$('sumOpenRepairs').textContent=Array.isArray(repairs)?repairs.filter(x=>!['completed','cancelled'].includes(x.status)).length:0;if($('sumRetired'))$('sumRetired').textContent=retired}catch(e){console.warn('[JMW DASHBOARD FIX]',e)}};setTimeout(run,250);window.jmwDashboardFixRefresh=run})();